    'res.dnsPublic' = @('Publiczny DNS {0}', 'Public DNS {0}', 'Öffentlicher DNS {0}')
    'res.dnsPublic.h' = @('Publiczne DNS są blokowane (port 53). Urządzenia SMA muszą wtedy używać DNS z DHCP - nie ustawiaj ręcznie 8.8.8.8 na urządzeniu.', 'Public DNS is blocked (port 53). SMA devices must then use the DNS from DHCP - do not set 8.8.8.8 manually on the device.', 'Öffentliche DNS-Server sind blockiert (Port 53). SMA-Geräte müssen dann den DNS aus DHCP nutzen - 8.8.8.8 nicht manuell am Gerät eintragen.')
    'sub.targets'   = @('Serwery SMA i cele kontrolne', 'SMA servers and control targets', 'SMA-Server und Kontrollziele')
    'res.dnsName'   = @('DNS: {0}', 'DNS: {0}', 'DNS: {0}')
    'res.dnsName.localfail.d' = @('Lokalny DNS nie rozwiązuje ({0}), publiczny tak: {1}', 'Local DNS does not resolve ({0}), public DNS does: {1}', 'Lokaler DNS löst nicht auf ({0}), öffentlicher schon: {1}')
    'res.dnsName.localfail.h' = @('Lokalny serwer DNS blokuje lub nie zna tej domeny (filtr DNS?). Odblokuj *.sunnyportal.com / *.sunnyportal.de / *.sunny-portal.com\nalbo ustaw na urządzeniu SMA publiczny DNS (np. 8.8.8.8).', 'The local DNS server blocks or does not know this domain (DNS filter?). Unblock *.sunnyportal.com / *.sunnyportal.de / *.sunny-portal.com\nor set a public DNS (e.g. 8.8.8.8) on the SMA device.', 'Der lokale DNS-Server blockiert diese Domain oder kennt sie nicht (DNS-Filter?). *.sunnyportal.com / *.sunnyportal.de / *.sunny-portal.com freigeben\noder am SMA-Gerät einen öffentlichen DNS (z. B. 8.8.8.8) einstellen.')
    'res.dnsName.fail.d' = @('Nazwa nie została rozwiązana przez żaden serwer DNS.', 'The name was not resolved by any DNS server.', 'Der Name wurde von keinem DNS-Server aufgelöst.')
    'res.dnsName.fail.h' = @('Brak rozwiązywania nazw - sprawdź DNS w routerze/firewallu (port UDP/TCP 53) oraz połączenie z Internetem.', 'No name resolution - check DNS in the router/firewall (port UDP/TCP 53) and the Internet connection.', 'Keine Namensauflösung - DNS in Router/Firewall (Port UDP/TCP 53) und Internetverbindung prüfen.')
    'res.dnsName.private.d' = @('Zwrócono adres prywatny/zerowy: {0}', 'Private/zero address returned: {0}', 'Private/Null-Adresse zurückgegeben: {0}')
    'res.dnsName.private.h' = @('Filtr DNS (firewall/serwer DNS) przekierowuje domenę SMA. Dodaj wyjątek dla domen SMA.', 'A DNS filter (firewall/DNS server) redirects the SMA domain. Add an exception for the SMA domains.', 'Ein DNS-Filter (Firewall/DNS-Server) leitet die SMA-Domain um. Ausnahme für die SMA-Domains anlegen.')
    'res.unblock.h' = @('Odblokuj w firewallu ruch wychodzący TCP {0} do {1} ({2}).\nZastosowanie: {3}.', 'Allow outbound TCP {0} to {1} ({2}) in the firewall.\nUsed by: {3}.', 'Ausgehenden TCP-Verkehr {0} zu {1} ({2}) in der Firewall freigeben.\nVerwendet von: {3}.')
    'res.tcpfail.d' = @('{0} - TCP: {1}', '{0} - TCP: {1}', '{0} - TCP: {1}')
    'res.tlsfail.d' = @('{0} - TCP OK ({1} ms), błąd TLS: {2}', '{0} - TCP OK ({1} ms), TLS error: {2}', '{0} - TCP OK ({1} ms), TLS-Fehler: {2}')
    'res.tlsfail.h' = @('Połączenie TCP działa, ale handshake TLS zostaje przerwany - typowe dla firewalli z filtrowaniem aplikacji / IPS lub inspekcją SSL. Dodaj wyjątek dla domen SMA.', 'The TCP connection works but the TLS handshake is interrupted - typical of firewalls with application filtering / IPS or SSL inspection. Add an exception for the SMA domains.', 'Die TCP-Verbindung funktioniert, aber der TLS-Handshake wird abgebrochen - typisch für Firewalls mit Applikationsfilter / IPS oder SSL-Inspection. Ausnahme für die SMA-Domains anlegen.')
    'res.inspect.d' = @('{0} - połączono, ale certyfikat: ''{1}'' (błędy: {2})', '{0} - connected, but certificate: ''{1}'' (errors: {2})', '{0} - verbunden, aber Zertifikat: ''{1}'' (Fehler: {2})')
    'res.inspect.h' = @('Prawdopodobna inspekcja SSL/TLS (podmiana certyfikatu przez firewall/proxy/antywirus) lub zły czas systemowy.\nUrządzenia SMA nie zaufają takiemu certyfikatowi - wyłącz inspekcję SSL dla *.sunnyportal.com i *.sunnyportal.de.', 'Probably SSL/TLS inspection (certificate replaced by firewall/proxy/antivirus) or wrong system time.\nSMA devices will not trust such a certificate - disable SSL inspection for *.sunnyportal.com and *.sunnyportal.de.', 'Wahrscheinlich SSL/TLS-Inspection (Zertifikat durch Firewall/Proxy/Virenschutz ersetzt) oder falsche Systemzeit.\nSMA-Geräte vertrauen einem solchen Zertifikat nicht - SSL-Inspection für *.sunnyportal.com und *.sunnyportal.de deaktivieren.')
    'res.smaca'     = @(' (certyfikat z CA SMA - prawidłowy)', ' (certificate from SMA CA - valid)', ' (Zertifikat der SMA-CA - gültig)')
    'res.tlsok.d'   = @('{0} - TCP {1} ms, TLS OK{2}, HTTP: {3}', '{0} - TCP {1} ms, TLS OK{2}, HTTP: {3}', '{0} - TCP {1} ms, TLS OK{2}, HTTP: {3}')
    'res.tcpok.d'   = @('{0} - połączono ({1} ms)', '{0} - connected ({1} ms)', '{0} - verbunden ({1} ms)')
    'res.9524.h'    = @('Port 9524 jest często blokowany w sieciach firmowych/szkolnych - bez niego Webconnect i Home Manager HM-20 nie wyślą danych.', 'Port 9524 is often blocked in company/school networks - without it Webconnect and Home Manager HM-20 cannot send data.', 'Port 9524 ist in Firmen-/Schulnetzen oft gesperrt - ohne ihn können Webconnect und Home Manager HM-20 keine Daten senden.')
    'res.ntpok.d'   = @('{0} - odpowiedź w {1} ms, różnica czasu urządzenia testującego: {2} s', '{0} - response in {1} ms, test device clock offset: {2} s', '{0} - Antwort in {1} ms, Zeitabweichung des Testgeräts: {2} s')
    'res.clock'     = @('Czas systemowy urządzenia testującego', 'Test device system time', 'Systemzeit des Testgeräts')
    'res.clock.d'   = @('Różnica {0} s względem serwera SMA', 'Offset {0} s compared to the SMA server', 'Abweichung {0} s gegenüber dem SMA-Server')
    'res.clock.h'   = @('Zły czas urządzenia testującego może powodować błędy certyfikatów w tym teście. Na urządzeniach SMA zły czas także blokuje TLS - sprawdź NTP na urządzeniu.', 'A wrong clock on the test device can cause certificate errors in this test. On SMA devices a wrong time also breaks TLS - check NTP on the device.', 'Eine falsche Uhrzeit am Testgerät kann in diesem Test Zertifikatsfehler verursachen. Auch auf SMA-Geräten verhindert eine falsche Zeit TLS - NTP am Gerät prüfen.')
    'res.ntpfail.d' = @('{0} - brak odpowiedzi NTP (UDP 123): {1}', '{0} - no NTP response (UDP 123): {1}', '{0} - keine NTP-Antwort (UDP 123): {1}')
    'res.ntpfail.h' = @('UDP 123 jest blokowany. Nie jest to krytyczne, jeśli router/inny serwer dostarcza czas przez NTP.\nW przeciwnym razie odblokuj UDP 123 do {0} - zły czas na urządzeniu uniemożliwia połączenia TLS.', 'UDP 123 is blocked. Not critical if the router/another server provides time via NTP.\nOtherwise allow UDP 123 to {0} - a wrong time on the device prevents TLS connections.', 'UDP 123 ist blockiert. Unkritisch, wenn der Router/ein anderer Server die Zeit per NTP liefert.\nAndernfalls UDP 123 zu {0} freigeben - eine falsche Zeit am Gerät verhindert TLS-Verbindungen.')
    'res.status'    = @('Status serwerów SMA', 'SMA server status', 'Status der SMA-Server')
    'res.status.h'  = @('Aktualne awarie i prace serwisowe po stronie SMA. Jeśli usługa ma tam zgłoszoną awarię, problem nie leży w sieci klienta.', 'Current outages and maintenance on the SMA side. If a service has a reported outage there, the problem is not in the customer network.', 'Aktuelle Störungen und Wartungsarbeiten bei SMA. Ist dort eine Störung gemeldet, liegt das Problem nicht im Kundennetz.')
    'res.status.fail.h' = @('Zanim zgłosisz blokadę, sprawdź, czy SMA nie ma awarii: {0}', 'Before reporting a block, check whether SMA has an outage: {0}', 'Vor der Meldung einer Sperre prüfen, ob bei SMA eine Störung vorliegt: {0}')
    'sub.diag'      = @('Diagnoza', 'Diagnosis', 'Diagnose')
    'res.diag'      = @('Diagnoza portalu', 'Portal diagnosis', 'Portal-Diagnose')
    'res.diag.noinet.d' = @('Brak dostępu do Internetu z tej karty (zawiodły również cele kontrolne).', 'No Internet access from this adapter (control targets failed too).', 'Kein Internetzugang über diesen Adapter (auch Kontrollziele fehlgeschlagen).')
    'res.diag.noinet.h' = @('Sprawdź bramę domyślną, router, kabel WAN, ewentualnie captive portal / uwierzytelnianie 802.1X w sieci firmowej.\nUrządzenia SMA w tej sieci też nie połączą się z portalem.', 'Check the default gateway, router, WAN cable, possibly a captive portal / 802.1X authentication in the company network.\nSMA devices in this network will not reach the portal either.', 'Standardgateway, Router, WAN-Kabel prüfen, ggf. Captive Portal / 802.1X-Authentifizierung im Firmennetz.\nSMA-Geräte in diesem Netz erreichen das Portal ebenfalls nicht.')
    'res.diag.sma.d'    = @('Internet działa, ale {0} z {1} usług SMA jest blokowanych/nieprawidłowych.', 'The Internet works, but {0} of {1} SMA services are blocked/faulty.', 'Das Internet funktioniert, aber {0} von {1} SMA-Diensten sind blockiert/fehlerhaft.')
    'res.diag.sma.h'    = @('Przekaż administratorowi sieci listę adresów i portów SMA (z raportu) do odblokowania w firewallu (ruch wychodzący, bez inspekcji SSL).', 'Give the network administrator the list of SMA addresses and ports (from the report) to allow in the firewall (outbound, without SSL inspection).', 'Dem Netzwerkadministrator die Liste der SMA-Adressen und -Ports (aus dem Bericht) zur Freigabe in der Firewall übergeben (ausgehend, ohne SSL-Inspection).')
    'res.diag.ok.d'     = @('Wszystkie usługi SMA są osiągalne z tej sieci.', 'All SMA services are reachable from this network.', 'Alle SMA-Dienste sind aus diesem Netz erreichbar.')
    'res.diag.ok.h'     = @('Jeśli urządzenia nadal nie łączą się z portalem, sprawdź na urządzeniu: DHCP/IP, bramę, DNS, czas (NTP) oraz czy jest w tym samym VLAN co urządzenie testujące.\nPrzy rejestracji w portalu sprawdź też numer seryjny, kod rejestracyjny (PIC/RID) i czy urządzenie nie jest przypisane do innej instalacji.', 'If the devices still do not connect to the portal, check on the device: DHCP/IP, gateway, DNS, time (NTP) and whether it is in the same VLAN as the test device.\nWhen registering in the portal also check the serial number, registration code (PIC/RID) and whether the device is assigned to another system.', 'Wenn sich die Geräte weiterhin nicht mit dem Portal verbinden, am Gerät prüfen: DHCP/IP, Gateway, DNS, Zeit (NTP) und ob es im selben VLAN wie das Testgerät ist.\nBei der Registrierung im Portal auch Seriennummer, Registrierungscode (PIC/RID) prüfen und ob das Gerät einer anderen Anlage zugeordnet ist.')

    # ---------------------------------------------------------------- urządzenia lokalne
    'hint.secondaryIp'  = @('Aby dostać się do urządzenia i zmienić jego konfigurację, dodaj tymczasowo na urządzeniu testującym drugi adres (jako administrator):\n  netsh interface ipv4 add address "{0}" {1} 255.255.255.0\nPo zakończeniu usuń go:  netsh interface ipv4 delete address "{0}" {1}', 'To reach the device and change its configuration, temporarily add a second address on the test device (as administrator):\n  netsh interface ipv4 add address "{0}" {1} 255.255.255.0\nRemove it afterwards:  netsh interface ipv4 delete address "{0}" {1}', 'Um das Gerät zu erreichen und umzukonfigurieren, vorübergehend eine zweite Adresse am Testgerät hinzufügen (als Administrator):\n  netsh interface ipv4 add address "{0}" {1} 255.255.255.0\nDanach wieder entfernen:  netsh interface ipv4 delete address "{0}" {1}')
    'cat.device'        = @('Urządzenie: {0}', 'Device: {0}', 'Gerät: {0}')
    'src.ip'            = @('podany adres IP', 'IP address given', 'angegebene IP-Adresse')
    'res.resolve'       = @('Rozwiązanie nazwy: {0}', 'Name resolution: {0}', 'Namensauflösung: {0}')
    'res.resolve.none.d'= @('brak ({0})', 'none ({0})', 'keine ({0})')
    'res.resolve.all'   = @('Rozwiązanie nazwy', 'Name resolution', 'Namensauflösung')
    'res.resolve.fail.d'= @('Żadna metoda (DNS, mDNS, NetBIOS) nie zwróciła adresu dla ''{0}''.', 'No method (DNS, mDNS, NetBIOS) returned an address for ''{0}''.', 'Keine Methode (DNS, mDNS, NetBIOS) lieferte eine Adresse für ''{0}''.')
    'res.resolve.fail.h'= @('Sprawdź pisownię hostname''u (urządzenia SMA mają zwykle domyślnie nazwę ''SMA'' + numer seryjny, np. SMA3012345678).\nRouter może nie rejestrować nazw klientów DHCP w DNS - sprawdź listę klientów DHCP w routerze.\nUżyj skanowania sieci, aby znaleźć urządzenia SMA po adresie MAC (00:40:AD) i Speedwire.\nJeśli skan też nic nie znajdzie: urządzenie jest w innej sieci/VLAN, niepodłączone lub wyłączone.', 'Check the hostname spelling (SMA devices usually have the default name ''SMA'' + serial number, e.g. SMA3012345678).\nThe router may not register DHCP client names in DNS - check the DHCP client list in the router.\nUse the network scan to find SMA devices by MAC address (00:40:AD) and Speedwire.\nIf the scan finds nothing either: the device is in another network/VLAN, not connected or switched off.', 'Schreibweise des Hostnamens prüfen (SMA-Geräte heißen standardmäßig meist ''SMA'' + Seriennummer, z. B. SMA3012345678).\nDer Router registriert DHCP-Clientnamen evtl. nicht im DNS - DHCP-Clientliste im Router prüfen.\nNetzwerk-Scan verwenden, um SMA-Geräte per MAC-Adresse (00:40:AD) und Speedwire zu finden.\nFindet auch der Scan nichts: Gerät ist in einem anderen Netz/VLAN, nicht verbunden oder ausgeschaltet.')
    'res.inconsistent'  = @('Niespójne adresy', 'Inconsistent addresses', 'Widersprüchliche Adressen')
    'res.inconsistent.h'= @('Różne metody zwracają różne adresy - prawdopodobnie nieaktualny wpis DNS (urządzenie zmieniło IP). Zaufaj adresowi, który odpowiada (ARP/ping poniżej).', 'Different methods return different addresses - probably a stale DNS entry (the device changed its IP). Trust the address that responds (ARP/ping below).', 'Verschiedene Methoden liefern verschiedene Adressen - vermutlich veralteter DNS-Eintrag (Gerät hat die IP geändert). Der antwortenden Adresse vertrauen (ARP/Ping unten).')
    'res.addr'          = @('Adres {0}', 'Address {0}', 'Adresse {0}')
    'res.self.d'        = @('To adres tego urządzenia testującego!', 'This is the address of this test device!', 'Das ist die Adresse dieses Testgeräts!')
    'res.self.h'        = @('Nazwa wskazuje na urządzenie testujące - sprawdź hostname. Jeśli to adres urządzenia SMA, mamy konflikt adresów IP.', 'The name points to the test device - check the hostname. If this is the SMA device address, there is an IP address conflict.', 'Der Name zeigt auf das Testgerät - Hostnamen prüfen. Ist es die Adresse des SMA-Geräts, liegt ein IP-Adresskonflikt vor.')
    'res.dev.apipa.d'   = @('Urządzenie ma adres APIPA (169.254.x.x) - nie otrzymało adresu z DHCP.', 'The device has an APIPA address (169.254.x.x) - it did not get an address from DHCP.', 'Das Gerät hat eine APIPA-Adresse (169.254.x.x) - es hat keine Adresse per DHCP erhalten.')
    'res.dev.apipa.h'   = @('Sprawdź serwer DHCP (router), kabel i port switcha urządzenia. Po przywróceniu DHCP zrestartuj urządzenie.', 'Check the DHCP server (router), the cable and the device''s switch port. Restart the device after DHCP is restored.', 'DHCP-Server (Router), Kabel und Switch-Port des Geräts prüfen. Nach Wiederherstellung von DHCP das Gerät neu starten.')
    'res.dev.outside.ping.d' = @('Poza podsiecią urządzenia testującego ({0}/{1}), ale odpowiada przez router ({2} ms).', 'Outside the test device subnet ({0}/{1}), but responds via the router ({2} ms).', 'Außerhalb des Subnetzes des Testgeräts ({0}/{1}), antwortet aber über den Router ({2} ms).')
    'res.dev.outside.ping.h' = @('Urządzenie jest w innej podsieci/VLAN. Komunikacja przez router działa dla unicastu, ale Speedwire/multicast (wykrywanie urządzeń, dane z licznika)\nNIE przechodzi przez routery. Master (Data Manager / Home Manager) i urządzenia podrzędne muszą być w tej samej podsieci i VLAN.', 'The device is in another subnet/VLAN. Communication via the router works for unicast, but Speedwire/multicast (device discovery, meter data)\ndoes NOT pass through routers. The master (Data Manager / Home Manager) and the slave devices must be in the same subnet and VLAN.', 'Das Gerät ist in einem anderen Subnetz/VLAN. Unicast über den Router funktioniert, aber Speedwire/Multicast (Geräteerkennung, Zählerdaten)\nwird NICHT über Router weitergeleitet. Master (Data Manager / Home Manager) und untergeordnete Geräte müssen im selben Subnetz und VLAN sein.')
    'res.dev.outside.d' = @('Poza podsiecią urządzenia testującego ({0}/{1}) i nie odpowiada.', 'Outside the test device subnet ({0}/{1}) and does not respond.', 'Außerhalb des Subnetzes des Testgeräts ({0}/{1}) und antwortet nicht.')
    'res.dev.outside.h' = @('Urządzenie ma najprawdopodobniej statyczny adres z innej sieci (np. po wymianie routera) lub jest w innym VLAN.\nUstaw na urządzeniu DHCP lub adres z podsieci {0}/{1}.', 'The device most likely has a static address from another network (e.g. after a router replacement) or is in another VLAN.\nSet the device to DHCP or to an address from subnet {0}/{1}.', 'Das Gerät hat höchstwahrscheinlich eine statische Adresse aus einem anderen Netz (z. B. nach Routertausch) oder ist in einem anderen VLAN.\nAm Gerät DHCP oder eine Adresse aus dem Subnetz {0}/{1} einstellen.')
    'res.dev.ok.mac.d'  = @('W podsieci, ping {0} ms, MAC {1}{2}', 'In subnet, ping {0} ms, MAC {1}{2}', 'Im Subnetz, Ping {0} ms, MAC {1}{2}')
    'res.dev.ok.d'      = @('W podsieci, ping {0} ms', 'In subnet, ping {0} ms', 'Im Subnetz, Ping {0} ms')
    'res.dev.arponly.d' = @('W podsieci, brak odpowiedzi na ping, ale ARP zwraca MAC {0}.', 'In subnet, no ping response, but ARP returns MAC {0}.', 'Im Subnetz, keine Ping-Antwort, aber ARP liefert MAC {0}.')
    'res.dev.arponly.h' = @('Urządzenie fizycznie jest w sieci (odpowiada na ARP), blokuje tylko ICMP. Sprawdź porty poniżej.', 'The device is physically in the network (answers ARP), it only blocks ICMP. Check the ports below.', 'Das Gerät ist physisch im Netz (antwortet auf ARP), blockiert nur ICMP. Ports unten prüfen.')
    'res.dev.none.d'    = @('W podsieci urządzenia testującego, ale brak odpowiedzi na ping i ARP.', 'In the test device subnet, but no response to ping or ARP.', 'Im Subnetz des Testgeräts, aber keine Antwort auf Ping und ARP.')
    'res.dev.none.h'    = @('Pod tym adresem nie ma urządzenia w tym segmencie sieci. Możliwe przyczyny:\n- nieaktualny wpis DNS (urządzenie dostało inny adres - sprawdź listę DHCP w routerze lub użyj skanowania),\n- urządzenie w innym VLAN mimo tej samej adresacji, izolacja klientów Wi-Fi (AP isolation),\n- urządzenie wyłączone / kabel / port switcha.', 'There is no device at this address in this network segment. Possible causes:\n- stale DNS entry (the device got another address - check the DHCP list in the router or use the scan),\n- device in another VLAN despite the same addressing, Wi-Fi client isolation (AP isolation),\n- device switched off / cable / switch port.', 'Unter dieser Adresse gibt es in diesem Netzsegment kein Gerät. Mögliche Ursachen:\n- veralteter DNS-Eintrag (Gerät hat eine andere Adresse - DHCP-Liste im Router prüfen oder Scan verwenden),\n- Gerät in anderem VLAN trotz gleicher Adressierung, WLAN-Client-Isolation (AP Isolation),\n- Gerät ausgeschaltet / Kabel / Switch-Port.')
    'res.vendor'        = @('Producent karty {0}', 'Network card vendor {0}', 'Hersteller der Netzwerkkarte {0}')
    'res.vendor.d'      = @('MAC {0} nie należy do SMA (00:40:AD).', 'MAC {0} does not belong to SMA (00:40:AD).', 'MAC {0} gehört nicht zu SMA (00:40:AD).')
    'res.vendor.h'      = @('Pod tym adresem odpowiada urządzenie innego producenta - możliwy konflikt adresów IP lub nieaktualny wpis DNS. (Niektóre moduły komunikacyjne mogą mieć inny prefiks MAC.)', 'A device from another vendor responds at this address - possible IP address conflict or stale DNS entry. (Some communication modules may use another MAC prefix.)', 'Unter dieser Adresse antwortet ein Gerät eines anderen Herstellers - möglicher IP-Adresskonflikt oder veralteter DNS-Eintrag. (Manche Kommunikationsmodule haben ein anderes MAC-Präfix.)')
    'res.port'          = @('Port TCP {0} {1} @ {2}', 'TCP port {0} {1} @ {2}', 'TCP-Port {0} {1} @ {2}')
    'res.port.open.d'   = @('otwarty ({0} ms)', 'open ({0} ms)', 'offen ({0} ms)')
    'res.webui'         = @('Interfejs WWW: {0}', 'Web interface: {0}', 'Weboberfläche: {0}')
    'res.webui.ok.d'    = @('Działa ({0}), HTTP: {1}', 'Works ({0}), HTTP: {1}', 'Funktioniert ({0}), HTTP: {1}')
    'res.webui.nores.d' = @('Nazwa nie jest rozwiązywana - pod tym adresem przeglądarka nie znajdzie urządzenia.', 'The name is not resolved - the browser will not find the device at this address.', 'Der Name wird nicht aufgelöst - unter dieser Adresse findet der Browser das Gerät nicht.')
    'res.webui.host.h'  = @('https://{0} działa tylko, gdy router rejestruje nazwy klientów DHCP w DNS albo działa NetBIOS/LLMNR.\nUżyj adresu IP lub https://{0}.local.', 'https://{0} only works if the router registers DHCP client names in DNS or NetBIOS/LLMNR works.\nUse the IP address or https://{0}.local.', 'https://{0} funktioniert nur, wenn der Router DHCP-Clientnamen im DNS registriert oder NetBIOS/LLMNR funktioniert.\nIP-Adresse oder https://{0}.local verwenden.')
    'res.webui.local.h' = @('https://{0}.local wymaga mDNS (multicast UDP 5353) w tym samym segmencie sieci. Brak odpowiedzi: inna podsieć/VLAN, izolacja klientów Wi-Fi, filtrowanie multicastu lub zapora.\nUżyj adresu IP.', 'https://{0}.local requires mDNS (multicast UDP 5353) in the same network segment. No response: other subnet/VLAN, Wi-Fi client isolation, multicast filtering or firewall.\nUse the IP address.', 'https://{0}.local erfordert mDNS (Multicast UDP 5353) im selben Netzsegment. Keine Antwort: anderes Subnetz/VLAN, WLAN-Client-Isolation, Multicast-Filterung oder Firewall.\nIP-Adresse verwenden.')
