    'res.webui.sum'     = @('Jak otworzyć interfejs WWW', 'How to open the web interface', 'So öffnen Sie die Weboberfläche')
    'res.webui.sum.h'   = @('Urządzenie SMA używa certyfikatu samopodpisanego - przeglądarka pokaże ostrzeżenie, które trzeba zaakceptować (Zaawansowane -> Przejdź do strony).', 'The SMA device uses a self-signed certificate - the browser shows a warning that has to be accepted (Advanced -> Proceed).', 'Das SMA-Gerät verwendet ein selbstsigniertes Zertifikat - der Browser zeigt eine Warnung, die bestätigt werden muss (Erweitert -> Weiter).')
    'res.webui.sum.none.d' = @('Interfejs WWW nie jest osiągalny pod żadnym adresem.', 'The web interface is not reachable at any address.', 'Die Weboberfläche ist unter keiner Adresse erreichbar.')
    'res.webui.sum.none.h' = @('Sprawdź wyniki powyżej (adres, podsieć, porty). Jeśli urządzenie jest w innej podsieci, dodaj tymczasowy drugi adres IP (polecenie netsh powyżej).', 'Check the results above (address, subnet, ports). If the device is in another subnet, add a temporary second IP address (netsh command above).', 'Ergebnisse oben prüfen (Adresse, Subnetz, Ports). Ist das Gerät in einem anderen Subnetz, vorübergehend eine zweite IP-Adresse hinzufügen (netsh-Befehl oben).')
    'res.web.h'         = @('Urządzenie odpowiada, ale bez interfejsu WWW - może to nie być urządzenie SMA z interfejsem (np. falownik bez Webconnect/Speedwire) lub to inny host.', 'The device responds but has no web interface - it may not be an SMA device with a web UI (e.g. inverter without Webconnect/Speedwire) or it is another host.', 'Das Gerät antwortet, hat aber keine Weboberfläche - evtl. kein SMA-Gerät mit Oberfläche (z. B. Wechselrichter ohne Webconnect/Speedwire) oder ein anderer Host.')
    'res.sw'            = @('Speedwire UDP 9522 @ {0}', 'Speedwire UDP 9522 @ {0}', 'Speedwire UDP 9522 @ {0}')
