    'res.smaAt'         = @('SMA {0}', 'SMA {0}', 'SMA {0}')
    'scan.outside'      = @('POZA podsiecią {0}/{1}!', 'OUTSIDE subnet {0}/{1}!', 'AUSSERHALB des Subnetzes {0}/{1}!')
    'scan.outside.h'    = @('Urządzenie jest fizycznie w tej samej sieci (odpowiedziało na multicast), ale ma adres z innej podsieci - najczęściej statyczny adres po zmianie routera.\nMaster go nie zobaczy przez unicast. Ustaw na urządzeniu DHCP lub poprawny adres.', 'The device is physically in the same network (it answered multicast), but has an address from another subnet - usually a static address after a router change.\nThe master will not see it via unicast. Set the device to DHCP or a correct address.', 'Das Gerät ist physisch im selben Netz (hat auf Multicast geantwortet), hat aber eine Adresse aus einem anderen Subnetz - meist eine statische Adresse nach Routertausch.\nDer Master sieht es per Unicast nicht. Am Gerät DHCP oder eine korrekte Adresse einstellen.')
    'res.scanSum'       = @('Podsumowanie skanowania', 'Scan summary', 'Scan-Zusammenfassung')
