    'res.socket.h'      = @('Port jest zajęty przez inny program (Sunny Explorer, SBFspot, Home Assistant itp.) - zamknij go i powtórz test.', 'The port is in use by another program (Sunny Explorer, SBFspot, Home Assistant etc.) - close it and repeat the test.', 'Der Port wird von einem anderen Programm belegt (Sunny Explorer, SBFspot, Home Assistant usw.) - Programm schließen und Test wiederholen.')
    'res.join'          = @('Dołączenie do grupy multicast', 'Multicast group join', 'Beitritt zur Multicast-Gruppe')
    'res.join.d'        = @('Gniazdo UDP 9522, grupa {0} na {1} (wysłano IGMP Join).', 'UDP 9522 socket, group {0} on {1} (IGMP join sent).', 'UDP-9522-Socket, Gruppe {0} auf {1} (IGMP-Join gesendet).')
    'res.packets'       = @('Odebrane pakiety Speedwire', 'Received Speedwire packets', 'Empfangene Speedwire-Pakete')
    'res.packets.none.d'= @('Brak jakichkolwiek pakietów w ciągu {0} s (wysłano też zapytania discovery).', 'No packets at all within {0} s (discovery requests were sent too).', 'Keinerlei Pakete innerhalb von {0} s (Discovery-Anfragen wurden ebenfalls gesendet).')
    'res.packets.none.h'= @('Możliwe przyczyny:\n- urządzenie testujące jest w innym VLAN/segmencie niż urządzenia SMA (sprawdź skanowanie sieci),\n- switch/router blokuje lub filtruje multicast (IGMP snooping bez querier''a, filtr multicast, ''multicast to unicast''),\n- Wi-Fi / punkt dostępowy nie przekazuje multicastu (izolacja klientów),\n- zapora Windows/antywirus na urządzeniu testującym blokuje UDP 9522 (patrz wyżej),\n- w sieci nie ma urządzeń Speedwire (np. tylko falowniki bez Speedwire/Webconnect).', 'Possible causes:\n- the test device is in another VLAN/segment than the SMA devices (check the network scan),\n- a switch/router blocks or filters multicast (IGMP snooping without querier, multicast filter, ''multicast to unicast''),\n- Wi-Fi / access point does not forward multicast (client isolation),\n- Windows Firewall/antivirus on the test device blocks UDP 9522 (see above),\n- there are no Speedwire devices in the network (e.g. only inverters without Speedwire/Webconnect).', 'Mögliche Ursachen:\n- das Testgerät ist in einem anderen VLAN/Segment als die SMA-Geräte (Netzwerk-Scan prüfen),\n- ein Switch/Router blockiert oder filtert Multicast (IGMP Snooping ohne Querier, Multicast-Filter, ''Multicast to Unicast''),\n- WLAN / Access Point leitet kein Multicast weiter (Client-Isolation),\n- Windows-Firewall/Virenschutz auf dem Testgerät blockiert UDP 9522 (siehe oben),\n- im Netz gibt es keine Speedwire-Geräte (z. B. nur Wechselrichter ohne Speedwire/Webconnect).')
    'mc.outside'        = @(' - adres POZA podsiecią {0}/{1}!', ' - address OUTSIDE subnet {0}/{1}!', ' - Adresse AUSSERHALB des Subnetzes {0}/{1}!')
    'mc.sn'             = @(', SN {0}', ', SN {0}', ', SN {0}')
    'mc.meter.d'        = @('{0}{1} - {2} pakietów w {3} s, max przerwa {4} s{5}', '{0}{1} - {2} packets in {3} s, max gap {4} s{5}', '{0}{1} - {2} Pakete in {3} s, max. Lücke {4} s{5}')
    'mc.gaps'           = @('(przerwa na początku/końcu: {0}/{1} s)', '(gap at start/end: {0}/{1} s)', '(Lücke am Anfang/Ende: {0}/{1} s)')
    'mc.gap.h'          = @('Dane z licznika docierają z przerwami. Licznik nadaje co ~1 s - przerwy oznaczają gubienie multicastu.\nTypowo: IGMP snooping na switchu bez IGMP querier''a (multicast zanika po ~2-5 min) - włącz IGMP querier na routerze/switchu lub wyłącz IGMP snooping.\nInne: Wi-Fi/powerline, przeciążona sieć, pętla w sieci, filtr ''broadcast/multicast storm control''.', 'Meter data arrives with gaps. The meter sends every ~1 s - gaps mean multicast is being lost.\nTypically: IGMP snooping on a switch without an IGMP querier (multicast stops after ~2-5 min) - enable an IGMP querier on the router/switch or disable IGMP snooping.\nOther: Wi-Fi/powerline, overloaded network, network loop, ''broadcast/multicast storm control'' filter.', 'Zählerdaten kommen mit Lücken an. Der Zähler sendet ca. jede Sekunde - Lücken bedeuten verlorenes Multicast.\nTypisch: IGMP Snooping am Switch ohne IGMP Querier (Multicast bricht nach ~2-5 min ab) - IGMP Querier am Router/Switch aktivieren oder IGMP Snooping deaktivieren.\nWeitere: WLAN/Powerline, überlastetes Netz, Netzwerkschleife, Filter ''Broadcast/Multicast Storm Control''.')
    'mc.meterOut.d'     = @('Licznik/Home Manager ma adres z innej podsieci.', 'The meter/Home Manager has an address from another subnet.', 'Zähler/Home Manager hat eine Adresse aus einem anderen Subnetz.')
    'mc.meterOut.h'     = @('Multicast dociera, ale unicast (konfiguracja, część komend) nie zadziała. Ustaw na urządzeniu DHCP lub adres z podsieci urządzenia testującego/mastera.', 'Multicast arrives, but unicast (configuration, some commands) will not work. Set the device to DHCP or to an address from the test device/master subnet.', 'Multicast kommt an, Unicast (Konfiguration, manche Befehle) funktioniert aber nicht. Am Gerät DHCP oder eine Adresse aus dem Subnetz des Testgeräts/Masters einstellen.')
    'res.swdev'         = @('Urządzenie Speedwire {0}', 'Speedwire device {0}', 'Speedwire-Gerät {0}')
    'mc.respOut.h'      = @('Urządzenie jest w tym samym segmencie (odpowiada na multicast), ale ma błędny adres IP - master nie nawiąże z nim komunikacji unicast.\nUstaw DHCP lub poprawny adres statyczny.', 'The device is in the same segment (answers multicast) but has a wrong IP address - the master will not establish unicast communication with it.\nSet DHCP or a correct static address.', 'Das Gerät ist im selben Segment (antwortet auf Multicast), hat aber eine falsche IP-Adresse - der Master kann keine Unicast-Kommunikation aufbauen.\nDHCP oder eine korrekte statische Adresse einstellen.')
    'res.discFrom'      = @('Zapytania discovery z {0}', 'Discovery requests from {0}', 'Discovery-Anfragen von {0}')
    'res.discFrom.d'    = @('{0} zapytań - prawdopodobnie master (Data Manager / Home Manager / narzędzie SMA) szuka urządzeń.', '{0} requests - probably a master (Data Manager / Home Manager / SMA tool) is searching for devices.', '{0} Anfragen - vermutlich sucht ein Master (Data Manager / Home Manager / SMA-Tool) nach Geräten.')
    'res.meter'         = @('Energy Meter / Home Manager', 'Energy Meter / Home Manager', 'Energy Meter / Home Manager')
    'res.meter.none.d'  = @('Nie odebrano danych z licznika/Home Managera.', 'No data received from a meter/Home Manager.', 'Keine Daten von Zähler/Home Manager empfangen.')
    'res.meter.none.h'  = @('Jeśli w instalacji jest Energy Meter lub Sunny Home Manager, jego multicast nie dociera do urządzenia testującego (inny segment/VLAN, filtrowanie multicastu, IGMP snooping).', 'If the system has an Energy Meter or Sunny Home Manager, its multicast does not reach the test device (other segment/VLAN, multicast filtering, IGMP snooping).', 'Wenn die Anlage einen Energy Meter oder Sunny Home Manager hat, erreicht dessen Multicast das Testgerät nicht (anderes Segment/VLAN, Multicast-Filter, IGMP Snooping).')
    'res.disc'          = @('Odpowiedzi na discovery', 'Discovery responses', 'Discovery-Antworten')
    'res.disc.none.d'   = @('Żadne urządzenie nie odpowiedziało na zapytanie Speedwire discovery.', 'No device answered the Speedwire discovery request.', 'Kein Gerät hat auf die Speedwire-Discovery-Anfrage geantwortet.')
    'res.disc.none.h'   = @('Wysłany multicast nie dociera do urządzeń lub ich odpowiedzi nie docierają do urządzenia testującego. Sprawdź filtrowanie multicastu na switchach/Wi-Fi oraz czy urządzenia mają włączony Speedwire.', 'The multicast sent does not reach the devices or their answers do not reach the test device. Check multicast filtering on switches/Wi-Fi and whether Speedwire is enabled on the devices.', 'Das gesendete Multicast erreicht die Geräte nicht oder deren Antworten erreichen das Testgerät nicht. Multicast-Filter an Switches/WLAN prüfen und ob Speedwire an den Geräten aktiviert ist.')
    'res.long'          = @('Długi test', 'Long test', 'Langzeittest')
